using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace HdrPilot {
public static class DuplicateLoaders {
 public static HashSet<string> Imports(string exe){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var stream=File.OpenRead(exe))using(var r=new BinaryReader(stream)){stream.Position=0x3c;int pe=r.ReadInt32();if(pe<0||pe+24>stream.Length)throw new Exception("Invalid executable.");stream.Position=pe;if(r.ReadUInt32()!=0x4550)throw new Exception("Invalid executable.");r.ReadUInt16();int count=r.ReadUInt16();stream.Position=pe+20;int optSize=r.ReadUInt16();long opt=pe+24;stream.Position=opt;bool x64=r.ReadUInt16()==0x20b;stream.Position=opt+(x64?112:96)+8;uint imports=r.ReadUInt32();var sections=new List<uint[]>();for(int i=0;i<count&&i<96;i++){stream.Position=opt+optSize+i*40+8;uint virtualSize=r.ReadUInt32(),virtualAddress=r.ReadUInt32(),rawSize=r.ReadUInt32(),rawAddress=r.ReadUInt32();sections.Add(new[]{virtualAddress,Math.Max(virtualSize,rawSize),rawAddress});}Func<uint,long> offset=v=>{var s=sections.FirstOrDefault(a=>v>=a[0]&&v-a[0]<a[1]);if(s==null)throw new Exception("Invalid import address.");return (long)s[2]+v-s[0];};if(imports==0)return names;long start=offset(imports);for(int i=0;i<4096;i++){stream.Position=start+i*20;if(stream.Position+20>stream.Length)break;uint first=r.ReadUInt32();r.ReadUInt32();r.ReadUInt32();uint name=r.ReadUInt32(),last=r.ReadUInt32();if(first==0&&name==0&&last==0)break;stream.Position=offset(name);var chars=new List<byte>();for(int j=0;j<260&&stream.Position<stream.Length;j++){byte b=r.ReadByte();if(b==0)break;chars.Add(b);}names.Add(System.Text.Encoding.ASCII.GetString(chars.ToArray()));}}return names;}
 public static DlssPlan Prepare(Game g){Core.Closed(g);if(g.ProtectedInstall)throw new Exception(g.Evidence);string root=Path.GetDirectoryName(Path.GetFullPath(g.Exe));var imports=Imports(g.Exe);var p=new DlssPlan{Folder=root,Uninstall=true,Summary=Appearance.Localize("Only byte-identical mod loaders in this folder are removed. One loader imported by the game is kept; native DLL copies in other folders are preserved.")};foreach(var group in AsiLoader.Installed(g).Concat(RenoDx.Loaders(root)).Concat(DlssCore.Proxies.Where(n=>DlssCore.IsOpti(DlssCore.Safe(root,n)))).Distinct(StringComparer.OrdinalIgnoreCase).GroupBy(n=>DlssCore.Hash(DlssCore.Safe(root,n)))){var names=group.ToList();if(names.Count<2)continue;string keep=names.Contains("ReShade64.dll")&&ModRemoval.Linked(g)?"ReShade64.dll":names.FirstOrDefault(n=>imports.Contains(n));if(keep==null)continue;p.Summary+="\nKeep: "+keep;foreach(string n in names.Where(n=>n!=keep&&!imports.Contains(n)))p.Changes.Add(new DlssChange{Name=n,Delete=true,Expected=group.Key});}if(p.Changes.Count==0)throw new Exception(Appearance.Localize("No duplicate loader can be safely removed automatically. Different folders, different contents or unverified loading paths are preserved."));return p;}
}
}
